import django.db.models.deletion
from django.db import migrations, models


def enlazar_equipos(apps, schema_editor):
    """Los equipos existentes pasan a la integracion de su reto (la primera creada).

    RET-03: antes de este enlace un profesor con cualquier integracion sobre el
    reto podia editar/eliminar equipos ajenos. Retrocedemos asignando cada equipo
    a la integracion mas antigua de su reto, que es la propietaria historica.
    """
    Equipo = apps.get_model("retos", "EquipoRetoAcademico")
    Integracion = apps.get_model("seguimiento", "IntegracionAcademica")
    for equipo in Equipo.objects.filter(integracion__isnull=True):
        integracion = Integracion.objects.filter(reto_id=equipo.reto_id).order_by("id").first()
        if integracion:
            equipo.integracion = integracion
            equipo.save(update_fields=["integracion"])


